$(() => {
  const 家前缀 = '三号楼1002';
  const 拖鞋 = '棉拖鞋';
  // 出门鞋从初始衣柜实际存在的鞋里按优先级选取，保证写进变量的鞋衣柜里真有
  const 出门鞋优先 = ['蓝色帆布鞋', '白色帆布鞋', '黑色皮质乐福鞋'];
  // 常见旧称/俗称 → 衣柜条目名
  const 鞋别名: Record<string, string> = { 小白鞋: '白色帆布鞋' };
  // 仅当用户明确表达与不变量冲突的意图时才让位；「换鞋出门」这类同向指令不算反向指令
  const 鞋袜反向指令 = /(光脚|赤脚|不穿|拖鞋)/;
  const 钥匙反向指令 = /(不带钥匙|别带钥匙|不用带钥匙|钥匙留在家里|忘带钥匙)/;

  function 找正文鞋(正文: string, 衣柜: Record<string, unknown>): string | undefined {
    const 直配 = 出门鞋优先.find(k => !!衣柜[k] && 正文.includes(k));
    if (直配) return 直配;
    const 别名 = Object.entries(鞋别名).find(([alias]) => 正文.includes(alias) && !!衣柜[鞋别名[alias]]);
    return 别名 ? 鞋别名[别名[0]] : undefined;
  }

  function 规范化鞋名(值: string, 衣柜: Record<string, unknown>): string | undefined {
    if (值 === '无' || !!衣柜[值]) return undefined;
    const 直配 = 出门鞋优先.find(k => !!衣柜[k] && 值.includes(k));
    if (直配) return 直配;
    const 别名 = Object.entries(鞋别名).find(([alias]) => 值.includes(alias) && !!衣柜[鞋别名[alias]]);
    return 别名 ? 鞋别名[别名[0]] : undefined;
  }

  /** 简化版露出程度（与状态栏 derive.ts 同一套权重；半褪计一半） */
  const 穿着权重: Record<string, number> = { 头部: 5, 面部: 5, 上衣: 20, 下装: 20, 腿部: 10, 脚部: 5, 胸罩: 15, 内裤: 15 };
  const 半褪关键词 = ['掀起', '撩起', '卷起', '半褪', '褪到', '褪至'];
  const 是半褪 = (s: string) => 半褪关键词.some(k => (s || '').includes(k));

  function 计算露出程度(穿着: Record<string, string>, 束缚: Record<string, string>): number {
    let 分数 = 0;
    for (const [部位, 权重] of Object.entries(穿着权重)) {
      const 描述 = (穿着?.[部位] ?? '').trim();
      if (!描述 || 描述 === '无') 分数 += 权重;
      else if (是半褪(描述)) 分数 += Math.round(权重 / 2);
    }
    const 束 = 束缚 ?? {};
    if (束.眼部 && 束.眼部 !== '无') 分数 += 10;
    if (束.脚踝 && 束.脚踝 !== '无') 分数 += 10;
    if (束.口部 && 束.口部 !== '无') 分数 += (束.口部 as string).includes('马具') ? 10 : 5;
    if (束.身体 && 束.身体 !== '无') 分数 += 8;
    if (束.腿部 && 束.腿部 !== '无') 分数 += 5;
    for (const p of ['颈部', '上肢', '手腕', '胸部', '乳头', '腰部', '阴部', '阴蒂', '小穴', '后穴', '足部']) {
      if (束[p] && 束[p] !== '无') 分数 += 3;
    }
    return Math.min(100, 分数);
  }

  waitGlobalInitialized('Mvu').then(() => {
    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (新变量, 旧变量) => {
      const 最新消息 = getChatMessages(-1)[0];
      if (!最新消息 || 最新消息.role !== 'assistant' || 最新消息.message_id === 0) return;
      const 最新楼层 = 最新消息.message_id;

      const 位置 = 新变量?.stat_data?.位置?.地点 as string | undefined;
      const 脚部 = 新变量?.stat_data?.穿着?.脚部 as string | undefined;
      const 携带 = 新变量?.stat_data?.当前携带 as string[] | undefined;
      if (typeof 位置 !== 'string' || typeof 脚部 !== 'string' || !Array.isArray(携带)) return;

      const 在家 = 位置.startsWith(家前缀);
      const 衣柜 = (新变量?.stat_data?.['$衣柜'] ?? {}) as Record<string, unknown>;
      const 玩家楼层 = getChatMessages(-2).filter(m => m.role === 'user').at(-1);
      const 玩家消息 = 玩家楼层?.message ?? '';

      // ===== 鞋名规范化（无条件执行，不受让位闸控制）：穿着鞋名必须逐字为衣柜条目名 =====
      if (脚部 !== '无') {
        const 规范 = 规范化鞋名(脚部, 衣柜);
        if (规范) _.set(新变量.stat_data, '穿着.脚部', 规范);
      }

      // ===== 不变量一/二：棉拖鞋不出家门、在家穿棉拖鞋 =====
      const 旧脚部 = 旧变量?.stat_data?.穿着?.脚部 as string | undefined;
      const 现脚部 = 新变量.stat_data.穿着.脚部 as string;
      const 脚部已由AI结算 = 旧脚部 !== undefined && 现脚部 !== 旧脚部;
      if (!脚部已由AI结算 && !(玩家消息 && 鞋袜反向指令.test(玩家消息))) {
        if (!在家 && 现脚部.includes('拖鞋')) {
          const 最终鞋 = 找正文鞋(最新消息.message, 衣柜) ?? 出门鞋优先.find(k => !!衣柜[k]) ?? '蓝色帆布鞋';
          _.set(新变量.stat_data, '穿着.脚部', 最终鞋);
        } else if (在家 && 现脚部 !== '无' && !现脚部.includes('拖鞋')) {
          _.set(新变量.stat_data, '穿着.脚部', 拖鞋);
        }
      }

      // ===== 不变量三：人不在家则必须带着家门钥匙 =====
      if (!在家 && !携带.includes('家门钥匙') && !(玩家消息 && 钥匙反向指令.test(玩家消息))) {
        _.set(新变量.stat_data, '当前携带', [...携带, '家门钥匙']);
      }

      // ===== 不变量四：回家必结算（行程中途的漏结算自动补记） =====
      const 旧位置 = 旧变量?.stat_data?.位置?.地点 as string | undefined;
      const 新记录 = (新变量.stat_data.露出记录 ?? []) as Array<Record<string, unknown>>;
      const 旧记录 = (旧变量?.stat_data?.露出记录 ?? []) as Array<Record<string, unknown>>;
      const 本轮已结算 = 新记录.length !== 旧记录.length;
      const 此前在户外 = typeof 旧位置 === 'string' && !旧位置.startsWith(家前缀);
      if (在家 && 此前在户外 && !本轮已结算) {
        // 回溯本次出门的各楼层（上一处家的楼层之后到上一楼为止），取行程中最高露出程度
        let 最高程度 = 0;
        let 代表地点 = 旧位置;
        try {
          const chat = SillyTavern.getContext().chat;
          let 上一个家的楼层 = -1;
          for (let i = 最新楼层 - 1; i >= 1; i--) {
            const m = chat[i];
            const sd = m?.variables?.[m.swipe_id ?? 0]?.stat_data;
            if (sd?.位置?.地点 && String(sd.位置.地点).startsWith(家前缀)) { 上一个家的楼层 = i; break; }
          }
          if (上一个家的楼层 >= 0) {
            for (let i = 上一个家的楼层 + 1; i < 最新楼层; i++) {
              const m = chat[i];
              const sd = m?.variables?.[m.swipe_id ?? 0]?.stat_data;
              if (!sd) continue;
              const 程度 = 计算露出程度(sd.穿着 ?? {}, sd.束缚 ?? {});
              if (程度 > 最高程度) { 最高程度 = 程度; if (sd.位置?.区域 && sd.位置?.地点) 代表地点 = `${sd.位置.区域}·${sd.位置.地点}`; }
            }
          }
        } catch (e) { /* 回溯失败则不补记，交由提示词层 */ }
        // 阈值 20：至少完整脱去/掀起两件才算一次值得补记的露出（单件半褪=10 不补，防误判）
        if (最高程度 >= 20) {
          const 时间 = 新变量.stat_data.时间;
          const 时间文本 = 时间 ? `${时间.周几} ${String(时间.小时).padStart(2, '0')}:${String(时间.分钟).padStart(2, '0')}` : '';
          新记录.push({
            时间: 时间文本,
            地点: 代表地点,
            程度: 最高程度,
            经验: Math.round(最高程度 / 2),
            结果: '成功',
            回想: '（补记）事后回味，心跳仍未平复',
          });
          _.set(新变量.stat_data, '露出记录', 新记录);
          _.set(新变量.stat_data, '露出经验', Math.max(0, Number(新变量.stat_data.露出经验 ?? 0) + Math.round(最高程度 / 2)));
        }
      }
    });
  });
});
